// ─── Parse Google Guaranteed lead email ───
const html = $input.item.json.html || $input.item.json.text || '';

// Helper: extract by label pattern
function extract(html, label) {
  const regex = new RegExp(label + '[^:]*:?\\s*</[^>]+>\\s*<[^>]+>([^<]+)', 'i');
  const m = html.match(regex);
  return m ? m[1].trim() : null;
}

// Extract fields
let name    = extract(html, 'Customer name') || extract(html, 'Name');
let phone   = extract(html, 'Phone') || extract(html, 'phone number');
let service = extract(html, 'Job type') || extract(html, 'Service') || extract(html, 'service requested');
let date    = extract(html, 'Date') || new Date().toISOString();

// Fallback: regex scan entire body for phone
if (!phone) {
  const phoneMatch = html.match(/\+?1?[\s.-]?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/);
  phone = phoneMatch ? phoneMatch[0] : null;
}

// Normalize phone to E.164 (+1XXXXXXXXXX)
if (phone) {
  phone = phone.replace(/[^\d+]/g, '');
  if (!phone.startsWith('+')) {
    phone = phone.length === 10 ? '+1' + phone : '+' + phone;
  }
}

return [{
  json: {
    name:    name    || 'Unknown',
    phone:   phone   || null,
    service: service || 'General inquiry',
    date:    date,
    raw_subject: $input.item.json.subject,
    parsed_ok: !!(name && phone)
  }
}];

