// ─── Check business hours (US Eastern, Miami) ───
const now = new Date();

// Convert to ET (UTC-5 standard / UTC-4 DST)
// Simple offset — for production use a proper timezone library
const utcHour = now.getUTCHours();
const month = now.getUTCMonth() + 1;
const isDST = month >= 3 && month <= 11; // approx DST window
const etHour = (utcHour - (isDST ? 4 : 5) + 24) % 24;
const dayOfWeek = now.getUTCDay(); // 0=Sun, 6=Sat

const isWeekday = dayOfWeek >= 1 && dayOfWeek <= 5;
const isBusinessHours = etHour >= 8 && etHour < 20; // 8am–8pm ET

return [{
  json: {
    ...$input.item.json,
    send_now: isWeekday && isBusinessHours,
    et_hour: etHour,
    day_of_week: dayOfWeek
  }
}];

